using System.Runtime.InteropServices;

class EnvVarCheck
{
    /// <summary>
    /// Checks whether an environment variable is defined in the process
    /// environment, even if its value is empty. Needed because .NET 9
    /// returns null for empty env vars on Linux.
    /// </summary>
    static bool IsEnvVarDefined(string name)
    {
        if (!RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
            return Environment.GetEnvironmentVariable(name) is not null;

        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            var prefix = name + "=";
            foreach (var entry in environ.Split('\0'))
            {
                if (entry.StartsWith(prefix, StringComparison.Ordinal))
                    return true;
            }
        }
        catch { }
        return false;
    }

